/* ----------------------------------------------------------------------------
 * Tokens
 * --------------------------------------------------------------------------*/
typedef enum {

T_DOT, T_COMMA, T_COLON, T_SEMI, T_PIPE, /* | for |params| and union */
 T_LPAREN, T_RPAREN, T_LBRACE, T_RBRACE, T_LBRACK, T_RBRACK,
 T_EOF, T_ERROR
} TokType;
typedef struct {
 TokType type;
 char *lexeme; /* owned copy */
 double num; /* for T_INT / T_FLOAT */
 int line;
} Token;
/* ----------------------------------------------------------------------------
 * AST
 * --------------------------------------------------------------------------*/
typedef enum {

N_EACH, /* coll.each |x| do ... end */
 N_PROGRAM
} NodeType;
typedef struct Node Node;
struct Node {
 NodeType type;
 int line;
 /* literal */
 double num;
 char *str; /* string / ident name / operator text */
 bool boolean;
 /* children */
 Node **kids;
 int nkids;
 int cap;
 /* function/struct/lambda */
 char **params;
 int nparams;
 Node *body;
};
Node *node_new(NodeType t, int line);
void node_push(Node *parent, Node *child);
void node_free(Node *n);
/* lexer */

typedef struct {
 const char *src;
 int pos, line;
} Lexer;
void lexer_init(Lexer *lx, const char *src);
Token lexer_next(Lexer *lx);
void token_free(Token *t);
const char *toktype_name(TokType t);
/* parser */
Node *parse_program(const char *src);
/* interpreter */
int interp_run(Node *program);
/* transpiler (Bada -> C) */
int transpile_to_c(Node *program, const char *out_path);
#endif /* BADA_H */
