 case T_INT:return"INT"; case T_FLOAT:return"FLOAT"; case T_STRING:return"STRING";
 case T_IDENT:return"IDENT"; case T_COMMIT:return">>"; case T_ARROW:return"=>";
 case T_DEFARROW:return":=>"; case T_WALRUS:return":="; case T_LARROW:return"<-";
 case T_CONSIST:return"~"; case T_SCOPE:return"::"; case T_REVISER:return"@reviser";
