static Token *cur(Parser*p){ return &p->toks[p->i]; }
static Token *peekn(Parser*p,int k){ int j=p->i+k; if(j>=p->n)j=p->n-1; return &p->toks[j]; }
static bool check(Parser*p,TokType t){ return cur(p)->type==t; }

static Token *advance(Parser*p){ Token*t=cur(p); if(p->i<p->n-1)p->i++; return t; }
static bool match(Parser*p,TokType t){ if(check(p,t)){advance(p);return true;} return false; }
static void perr(Parser*p,const char*msg){
 fprintf(stderr,"[parse error] line %d near '%s': %s\n",
 cur(p)->line, cur(p)->lexeme?cur(p)->lexeme:"?", msg);
 p->errors++;
}
