1106 default: exec_stmt(d,e); break;
1107 }
1108 }
1110 static void hoist_funcs(Node*scope, Env*e){
1111 for(int i=0;i<scope->nkid;i++){
1112 Node*d=scope->kids[i];

1113 if(d->kind==N_FUNC) register_func(d,e);
1114 else if(d->kind==N_OMEGABLOCK && d->nkid) hoist_funcs(d->kids[0],e);
1115 else if(d->kind==N_REVISER) {
1116 for(int j=0;j<d->nkid;j++) if(d->kids[j]->kind==N_FUNC) register_func(d->kids[j],e);
1117 }
1118 }
1119 }
1121 static void run_program(Node*prog){
1122 GLOBAL=env_new(NULL);
1123 for(int i=0;i<B_NBUILTIN;i++){ Value v; v.kind=V_BUILTIN; v.builtin=i; env_bind(GLOBAL,BNAMES[i],v); }

1124 for(int i=0;i<prog->nkid;i++) if(prog->kids[i]->kind==N_REVISER) exec_reviser(prog->kids[i],GLOBAL);
1125 hoist_funcs(prog,GLOBAL);
1126 for(int i=0;i<prog->nkid;i++){
1127 Node*d=prog->kids[i];
1128 if(d->kind==N_FUNC||d->kind==N_REVISER) continue;
1129 exec_decl(d,GLOBAL);
1130 }
1131 }
1133 static void dump_tokens(Token*t){
1134 for(size_t i=0;;i++){
1135 Token*k=&t[i];
1136 printf("%-12s", tok_name(k->kind));

1137 if(k->kind==T_INT||k->kind==T_FLOAT) printf(" %g", k->num);
1138 else if(k->lex) printf(" %s", k->lex);
1139 printf("\n");
1140 if(k->kind==T_EOF) break;
1141 }
1142 }
1144 static char *read_file(const char*path){
1145 FILE*f=fopen(path,"rb"); if(!f){ fprintf(stderr,"cannot open %s\n",path); exit(1); }
1146 fseek(f,0,SEEK_END); long n=ftell(f); fseek(f,0,SEEK_SET);
1147 char*b=xmalloc(n+1); size_t r=fread(b,1,n,f); b[r]=0; fclose(f); return b;
1148 }

1150 static Node* parse_source(const char*src, Token**toks_out){
1151 POSTFIX_WORDS.n=0; STMT_WORDS.n=0;
1152 Lexer L; memset(&L,0,sizeof L); L.src=src; L.len=strlen(src); L.line=1;
1153 lex_all(&L);
1154 if(toks_out) *toks_out=L.toks;
1155 Parser P; P.t=L.toks; P.i=0; P.n=L.ntok;
1156 return parse_program(&P);
1157 }
1159 int main(int argc, char**argv){
1160 if(argc<3){ fprintf(stderr,"usage: %s <run|tokens|ast> file.bada\n",argv[0]); return 1; }

1161 const char*cmd=argv[1];
1162 const char*path=argv[2];
1163 char*src=read_file(path);
1164 if(!strcmp(cmd,"tokens")){ Token*t; parse_source(src,&t); dump_tokens(t); return 0; }
1165 if(!strcmp(cmd,"run")){ Node*prog=parse_source(src,NULL); run_program(prog); return 0; }
1166 fprintf(stderr,"unknown command: %s\n",cmd);
1167 return 1;
1168 }
